def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone, timedelta

    try:
        # Validate nanoseconds input
        if not isinstance(nanoseconds, int):
            raise ValueError("Nanoseconds must be an integer.")

        # Calculate seconds and remaining nanoseconds
        seconds = nanoseconds // 1_000_000_000
        nanos = nanoseconds % 1_000_000_000

        # Create a datetime object from the epoch with the calculated seconds and nanoseconds
        dt = datetime(1970, 1, 1) + timedelta(seconds=seconds, microseconds=nanos // 1000)

        # If timezone is provided, localize the time
        if tz is not None:
            if not isinstance(tz, timezone):
                raise ValueError("Timezone must be a datetime.timezone object.")
            dt = dt.replace(tzinfo=timezone.utc).astimezone(tz)
            return dt.time().replace(tzinfo=tz)
        else:
            return dt.time()
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise ValueError("Expected a timedelta instance")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

