def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from itertools import islice
    from concurrent.futures import ThreadPoolExecutor, as_completed

    if not cmd:
        raise ValueError("Command must be provided.")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1.")

    def _chunked(it, size):
        it = iter(it)
        return iter(lambda: tuple(islice(it, size)), ())

    def _run_command(args):
        try:
            result = subprocess.run(
                cmd + args,
                check=True,
                capture_output=True,
                text=False,
                **kwargs,
            )
            return result.returncode, result.stdout
        except subprocess.CalledProcessError as e:
            return e.returncode, e.stdout

    max_length = _max_length - sum(len(arg) for arg in cmd) - len(cmd) - 1
    if max_length <= 0:
        raise ValueError("Maximum command length is too small to accommodate the base command.")

    chunk_size = 1
    while chunk_size < len(varargs):
        estimated_length = sum(len(arg) + 1 for arg in islice(varargs, chunk_size))
        if estimated_length > max_length:
            break
        chunk_size += 1

    if chunk_size == 1:
        raise ValueError("Command length limit is too small to accommodate any arguments.")

    results = []
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = {executor.submit(_run_command, args): args for args in _chunked(varargs, chunk_size)}
        for future in as_completed(futures):
            try:
                returncode, output = future.result()
                results.append((returncode, output))
            except Exception as e:
                results.append((1, str(e).encode()))

    final_returncode = 0 if all(rc == 0 for rc, _ in results) else 1
    final_output = b''.join(output for _, output in results)
    return final_returncode, final_output

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        raise ValueError("Command tuple cannot be empty")

    try:
        # Convert the command to a list to allow modifications
        cmd_list = list(cmd)

        # Check if the first element is a script with a shebang
        if cmd_list[0].endswith(('.py', '.pyw')):
            # Prepend 'python' to the command to ensure it's run with the Python interpreter
            cmd_list.insert(0, 'python')

        # Convert the list back to a tuple
        return tuple(cmd_list)

    except Exception as e:
        raise RuntimeError(f"An error occurred while normalizing the command: {e}")

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    from functools import lru_cache as _lru_cache

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

