def check_digests_present_and_used(self, manifest_files, digests_used):
    if not isinstance(manifest_files, dict):
        raise ValueError("manifest_files must be a dictionary.")
    if not isinstance(digests_used, set):
        raise ValueError("digests_used must be a set.")

    all_digests = set()
    for file_data in manifest_files.values():
        if not isinstance(file_data, dict) or 'digest' not in file_data:
            raise ValueError("Each entry in manifest_files must be a dictionary containing a 'digest' key.")
        all_digests.add(file_data['digest'])

    missing_digests = all_digests - digests_used
    if missing_digests:
        raise ValueError(f"Digests present in manifest but not used: {missing_digests}")

