def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        tznames = namefunc()
        if isinstance(tznames, tuple) and all(isinstance(tz, unicode) for tz in tznames):
            return tuple(tz.encode('utf-8') for tz in tznames)
        return tznames
    except Exception as e:
        raise ValueError("An error occurred while processing tzname: {}".format(e))

