def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    try:
        # Assuming self.root is the starting point of the hierarchy
        stack = [self.root]
        while stack:
            current = stack.pop()
            if hasattr(current, 'children'):
                stack.extend(current.children)
            if validate_objects:
                num_objects += 1
                if self._is_valid_object(current, check_digests):
                    good_objects += 1
                elif show_warnings:
                    print(f"Warning: Object {current} is not valid.")
    except Exception as e:
        print(f"An error occurred during validation: {e}")

    return num_objects, good_objects

