def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet list cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise ValueError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise ValueError("register_value must be a string")

    try:
        for key, value in flow_params.items():
            if isinstance(value, dict):
                _replace_register(value, register_number, register_value)
            elif value == register_value:
                flow_params[key] = register_number
    except Exception as e:
        raise RuntimeError(f"An error occurred while replacing register: {e}")

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("The 'value' parameter must be a string.")
    if not isinstance(arg, str):
        raise ValueError("The 'arg' parameter must be a string.")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Input must be a class")

    subclasses_list = []

    def _get_subclasses(current_class):
        nonlocal subclasses_list
        subclasses_list.extend(current_class.__subclasses__())
        for subclass in current_class.__subclasses__():
            _get_subclasses(subclass)

    _get_subclasses(cls)
    return subclasses_list

