def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Split the output into lines and extract file names
        ignored_files = [line.split()[-1] for line in result.stdout.strip().split('\n') if line]

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string separated by commas
        return ','.join(ignored_files)

    except subprocess.CalledProcessError as e:
        # Handle the case where the git command fails
        return f"Error: {e.stderr.strip()}"
    except Exception as e:
        # Handle any other exceptions
        return f"An unexpected error occurred: {str(e)}"

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Frequency must be in the format 'number unit'")

        number = int(parts[0])
        unit = parts[1].lower()

        if unit in ['second', 'seconds']:
            return datetime.timedelta(seconds=number)
        elif unit in ['minute', 'minutes']:
            return datetime.timedelta(minutes=number)
        elif unit in ['hour', 'hours']:
            return datetime.timedelta(hours=number)
        elif unit in ['day', 'days']:
            return datetime.timedelta(days=number)
        elif unit in ['week', 'weeks']:
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Cannot parse frequency '{frequency}': {e}")

def make_find_paths(find_paths):
    def is_pattern(s):
        return '*' in s or '?' in s or '[' in s or ']' in s

    transformed_paths = []
    for path in find_paths:
        if not is_pattern(path) and ':' not in path:
            # Transform path fragment into a glob pattern
            transformed_path = f'sh:**/*{path}*/**'
        else:
            # Pass through existing patterns or paths with colon untouched
            transformed_path = path
        transformed_paths.append(transformed_path)
    return transformed_paths

