def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: A string or a list of strings representing the script.
    :param separator: A string used to separate commands in the one-liner.
    :return: A single string with the script commands separated by the separator.
    """
    try:
        if isinstance(script, str):
            script = script.splitlines()
        elif not isinstance(script, list):
            raise ValueError("Script must be a string or a list of strings.")

        # Filter out empty lines
        script = [line.strip() for line in script if line.strip()]

        return separator.join(script)
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher
    except ValueError:
        raise ValueError("Matcher must be a tuple containing the name and an optional default value.")

    value = os.getenv(name, default)
    if value is None:
        raise EnvironmentError(f"Environment variable '{name}' is not defined and no default value was provided.")

    return value

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("Input must be a list of strings")

    processed_list = []
    for item in input_list:
        if not isinstance(item, str):
            raise TypeError("All elements in the list must be strings")
        if len(item) > 1 and item.endswith(os.sep):
            item = item[:-1]
        processed_list.append(item)

    return processed_list

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("Pattern must be a string")

    if strip:
        pattern = pattern.strip()

    try:
        regex_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    return regex_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("Commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("Arguments must be a list of strings.")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, stderr=stderr, check=True)

        if verbose:
            print("Command output:", result.stdout)

        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with error:", e.stderr)
        raise
    except Exception as e:
        if verbose:
            print("An error occurred:", str(e))
        raise

