def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        # Find all nodes that are not children in any (child, prop, parent) triple
        children = {triple[0] for triple in graph.triples((None, prop, None))}
        parents = {triple[2] for triple in graph.triples((None, prop, None))}
        roots.update(parents - children)
        return roots
    except Exception as e:
        raise ValueError(f"An error occurred while finding roots: {e}")

