def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        if not isinstance(shape, tuple):
            raise ValueError("Shape must be a tuple.")
        if not all(isinstance(dim, int) and dim > 0 for dim in shape):
            raise ValueError("All dimensions in shape must be positive integers.")
        if not isinstance(dtype, np.dtype):
            raise ValueError("Dtype must be a numpy.dtype.")
        return np.empty(shape, dtype=dtype)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except (FileNotFoundError, PermissionError) as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True))
            continue
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=e.lineno, msg=str(e), args=(), exc_info=True))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        config_dict[filename] = {**config, **overrides}

    return config_dict, log_records

def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise ValueError("ticks must be an integer")
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    seconds, nanoseconds = divmod(ticks, 1000000000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return cls(hours, minutes, seconds, nanoseconds, tz)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if not isinstance(values, (list, tuple, set)):
        raise ValueError("Values must be an iterable of strings.")

    for value in values:
        if not isinstance(value, str):
            raise ValueError("All values must be strings.")
        if not value.isascii():
            raise ValueError("All string values must be ASCII.")

    # Assuming Bookmarks is a class that can be initialized with a list of strings
    return cls(values)

