def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("Input must be a string")

    try:
        from dateutil import parser
        from dateutil.tz import tzoffset, gettz

        if ignoretz:
            return parser.parse(timestr, default=default, ignoretz=ignoretz, **kwargs)

        if tzinfos is not None:
            if isinstance(tzinfos, dict):
                for tzname, tzinfo in tzinfos.items():
                    if isinstance(tzinfo, int):
                        tzinfos[tzname] = tzoffset(tzname, tzinfo)
                    elif not isinstance(tzinfo, tzinfo):
                        raise ValueError("tzinfo values must be int offsets or tzinfo objects")
            elif not callable(tzinfos):
                raise ValueError("tzinfos must be a dictionary or a callable")

        return parser.parse(timestr, default=default, tzinfos=tzinfos, **kwargs)

    except parser.ParserError as e:
        raise parser.ParserError(f"Error parsing date: {e}")
    except OverflowError as e:
        raise OverflowError(f"Date exceeds the largest valid C integer: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("Input must be a datetime.datetime object.")
    if dt.tzinfo is None:
        raise ValueError("Input datetime must be timezone-aware.")

    # Convert the given UTC datetime to the timezone of self
    local_dt = self.normalize(self.localize(dt.replace(tzinfo=None)))

    # Check if the datetime is in a fold state
    if self.localize(dt.replace(tzinfo=None), is_dst=None) is not None:
        # Determine if it's the first occurrence of the ambiguous datetime
        is_first_occurrence = self.localize(dt.replace(tzinfo=None), is_dst=True) == local_dt
        if not is_first_occurrence:
            local_dt = self.localize(dt.replace(tzinfo=None), is_dst=False)

    return local_dt

def default_tzinfo(dt, tzinfo):
    if not isinstance(dt, datetime.datetime):
